{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Bath Immersions</title>
  <meta name="description" content="Sensory sound bath events, private sessions, and premium restorative experiences in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="theme-root">
  <svg class="site-pattern" aria-hidden="true">
    <defs>
      <pattern id="bgPattern" patternUnits="userSpaceOnUse" width="200" height="200">
        <rect width="200" height="200" fill="url(#g)" />
      </pattern>
      <linearGradient id="g" x1="0" x2="1">
        <stop offset="0%" stop-color="#f7f3ff"/>
        <stop offset="100%" stop-color="#e8fbff"/>
      </linearGradient>
    </defs>
    <rect width="100%" height="100%" fill="url(#bgPattern)" />
  </svg>

  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" id="mainNav">
        <a href="/">Gatherings</a>
        <a href="events.html">Next Wave</a>
        <a href="private-sessions.html">Private Sessions</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">About</a>
        <a href="faq.html">Questions</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="nav-toggle" id="navToggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-text">
          <h1 class="headline">Drift into resonance — a curated sound bath in {{CITY}}</h1>
          <p class="lead">Join {{FACILITATOR_NAME}} for immersive, sensory journeys that combine carefully tuned instruments and ceremonial pacing to soothe body and mind.</p>
          <div class="hero-ctas">
            <a class="button primary" href="events.html">Upcoming Immersion — {{NEXT_EVENT_DATE}}</a>
            <a class="button light" href="book.html">Reserve a Mat</a>
          </div>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg viewBox="0 0 600 400" class="hero-svg">
            <defs>
              <linearGradient id="hg" x1="0" x2="1"><stop offset="0%" stop-color="#7bdff6"/><stop offset="100%" stop-color="#9b7bff"/></linearGradient>
              <filter id="glow"><feGaussianBlur stdDeviation="20" result="b"/></filter>
            </defs>
            <g filter="url(#glow)">
              <ellipse cx="300" cy="200" rx="220" ry="110" fill="url(#hg)" opacity="0.28"/>
              <circle cx="220" cy="150" r="60" fill="#fff" opacity="0.06"/>
              <circle cx="380" cy="250" r="80" fill="#fff" opacity="0.05"/>
            </g>
            <g class="rings" stroke="#ffffff55" stroke-width="2" fill="none">
              <circle cx="300" cy="200" r="40" />
              <circle cx="300" cy="200" r="80" />
              <circle cx="300" cy="200" r="140" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section class="myth-truth">
      <div class="wrap">
        <h2>Myth vs. Truth</h2>
        <div class="grid-2 myths">
          <div class="card">
            <h3>Myth: It’s just background noise</h3>
            <p>Sound baths are passive and vague — a fad for the curious.</p>
          </div>
          <div class="card truth">
            <h3>Truth: Deliberate sound is therapeutic</h3>
            <p>Our sessions use tuned instruments, breathwork cues, and pacing to guide nervous system regulation. Every tone and pause has intention.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section class="pillars">
      <div class="wrap">
        <h2>Foundational Elements</h2>
        <div class="grid-3">
          <article class="pillar">
            <h4>Sonic Design</h4>
            <p>Instrument selection varies — expect crystal bowls, a deep gong, and delicate chimes woven with tuning forks for overtones.</p>
          </article>
          <article class="pillar">
            <h4>Space & Comfort</h4>
            <p>We craft warm, layered textures: blankets, bolsters, dim lighting and a plush acoustical layout to feel contained and safe.</p>
          </article>
          <article class="pillar">
            <h4>Facilitation</h4>
            <p>{{FACILITATOR_NAME}} combines training, intuition and ceremony to create clear transitions, anchors, and closing integration.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- CASE NOTES -->
    <section class="case-notes">
      <div class="wrap">
        <h2>Recent Session Notes</h2>
        <ul>
          <li><strong>Restoration:</strong> Evening immersion with monochord harmonics — participants reported deeper breath and 30% drop in subjective tension.</li>
          <li><strong>Collective Shift:</strong> Gong-led closing released long-held shoulder tension for several attendees.</li>
          <li><strong>Gentle Reset:</strong> Short mid-day sound lounge featuring tuning forks and soft bowls for corporate wellness.</li>
        </ul>
      </div>
    </section>

    <!-- FAQ (brief) -->
    <section class="faq-preview">
      <div class="wrap">
        <h2>Quick Questions</h2>
        <div class="qa-grid">
          <div>
            <h4>What should I bring?</h4>
            <p>Bring a yoga mat, a thick blanket, pillow or bolster, and a water bottle. We provide extras on request.</p>
          </div>
          <div>
            <h4>Are there contraindications?</h4>
            <p>Pregnancy, epilepsy, and recent major surgery may require clearance. If you have a pacemaker or serious medical condition, please consult your physician and inform us ahead of time.</p>
          </div>
          <div>
            <h4>What is the flow?</h4>
            <p>We begin with a gentle settling, guided breathwork, a 45–60 minute sound sequence with intentional crescendos and rests, and finish with grounding integration and tea.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta-panel">
      <div class="wrap cta-inner">
        <div>
          <h3>Attend a session in {{VENUE_NAME}}</h3>
          <p>Reserve a space for our next immersive experience. Limited mats to preserve intimacy.</p>
        </div>
        <div class="cta-actions">
          <a class="button primary" href="events.html">See Upcoming Dates</a>
          <a class="button light" href="book.html">Book a Private Session</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-col">
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
      </div>
      <div class="foot-col">
        <a href="contact.html">Contact</a>
        <a href="faq.html">FAQs</a>
        <a href="about.html">The Team</a>
      </div>
      <div class="foot-col">
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
    <div class="wrap smallprint">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
  </footer>

</body>
</html>"} 
