{"path":"assets/css/styles.css","content":"/* Bold playful + mystic modern theme */
:root{
  --bg:#0f1020;
  --card:#0b1220;
  --accent1:#7bdff6;
  --accent2:#9b7bff;
  --muted:#cbd5e1;
  --glass:rgba(255,255,255,0.06);
  --radius:14px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, 'Helvetica Neue', Arial; margin:0; background:linear-gradient(180deg, #f7f3ff 0%, #e8fbff 100%); color:#071029;}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-pattern{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;opacity:0.45;mix-blend-mode:soft-light}
.site-header{position:sticky;top:0;background:linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0.35));backdrop-filter: blur(6px);border-bottom:1px solid rgba(7,16,41,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:20px}
.brand{font-weight:700;color:var(--accent2);text-decoration:none;font-size:1.05rem}
.nav{margin-left:auto;display:flex;gap:18px;align-items:center}
.nav a{color:#071029;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.cta, .button.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#072; color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none}
.nav a:hover{opacity:0.9}
.nav-toggle{display:none;background:none;border:0;font-size:1.4rem}

.hero{padding:64px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:24px;align-items:center}
.headline{font-size:2.2rem;margin:0 0 12px 0;color:#081229}
.lead{color:var(--muted);margin:0 0 18px 0}
.hero-visual{border-radius:18px;overflow:hidden}
.hero-svg{width:100%;height:auto;display:block}
.button{display:inline-block}
.button.light{background:transparent;border:1px solid rgba(7,16,41,0.06);padding:10px 14px;border-radius:10px}

.myth-truth{padding:54px 0}
.myth-truth h2{margin:0 0 18px 0}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.card{background:var(--glass);padding:18px;border-radius:12px}
.card.truth{background:linear-gradient(90deg, rgba(155,123,255,0.12), rgba(123,223,246,0.08));}

.pillars{padding:54px 0}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.pillar{background:#fff;padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(11,18,32,0.06)}

.case-notes{padding:44px 0}
.case-notes ul{margin:12px 0 0 18px;color:#28323f}

.faq-preview{padding:36px 0;background:linear-gradient(180deg, rgba(155,123,255,0.03), rgba(123,223,246,0.02));border-radius:12px}
.qa-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.qa-grid h4{margin:0 0 6px 0}

.cta-panel{padding:26px 0;margin-top:28px}
.cta-inner{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(90deg, rgba(123,223,246,0.06), rgba(155,123,255,0.06));padding:18px;border-radius:14px}
.cta-actions{display:flex;gap:12px}

.site-footer{margin-top:34px;padding:26px 0;background:linear-gradient(180deg, rgba(7,16,41,0.02), rgba(7,16,41,0.01));color:#28323f}
.site-footer .wrap{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}
.site-footer a{color:#071229;text-decoration:none}
.smallprint{padding:10px 28px;color:#6e7580;font-size:0.9rem}

/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .grid-3{grid-template-columns:1fr}
  .grid-2{grid-template-columns:1fr}
  .qa-grid{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
}

/* playful rings animation */
.rings circle{animation:expand 8s ease-in-out infinite}
.rings circle:nth-child(2){animation-delay:1s}
.rings circle:nth-child(3){animation-delay:2s}
@keyframes expand{0%{opacity:0.45;transform:scale(0.6)}50%{opacity:0.12;transform:scale(1)}100%{opacity:0.0;transform:scale(1.4)}}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactions: mobile nav, year update, smooth anchors
document.addEventListener('DOMContentLoaded',function(){
  var nav = document.getElementById('mainNav');
  var toggle = document.getElementById('navToggle');
  if(toggle){
    toggle.addEventListener('click',function(){
      if(nav.style.display === 'flex'){nav.style.display='none'} else {nav.style.display='flex';nav.style.flexDirection='column'}
    });
  }
  // set year
  var y = new Date().getFullYear();
  var el = document.getElementById('year'); if(el) el.textContent = y;

  // smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var id = this.getAttribute('href').slice(1); var target = document.getElementById(id); if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth'});} 
    });
  });

  // small accessibility: prefers-reduced-motion
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    document.querySelectorAll('.rings circle').forEach(function(c){c.style.animation='none'});
  }
});"} 
